"use strict";(self.webpackChunkpython_bridge_docs=self.webpackChunkpython_bridge_docs||[]).push([[166],{2310:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"willkommen","metadata":{"permalink":"/python-bridge/blog/willkommen","source":"@site/blog/2026-09-06-willkommen.md","title":"Willkommen bei Python Bridge","description":"Python Bridge verbindet Godot 4 mit Python \u2014 ohne Python in eine eigene","date":"2026-09-06T00:00:00.000Z","tags":[{"inline":true,"label":"release","permalink":"/python-bridge/blog/tags/release"},{"inline":true,"label":"godot","permalink":"/python-bridge/blog/tags/godot"},{"inline":true,"label":"python","permalink":"/python-bridge/blog/tags/python"}],"readingTime":0.795,"hasTruncateMarker":true,"authors":[{"name":"Python Bridge Team","role":"Maintainer","url":"https://github.com/CyberToshi/python-bridge","key":"python-bridge-team","page":null}],"frontMatter":{"slug":"willkommen","title":"Willkommen bei Python Bridge","authors":["python-bridge-team"],"tags":["release","godot","python"],"date":"2026-09-06T00:00:00.000Z"},"unlisted":false},"content":"**Python Bridge** verbindet Godot 4 mit Python \u2014 ohne Python in eine eigene\\r\\nSprache zu verwandeln. Du schreibst weiterhin normale `.py`-Dateien, und\\r\\nGDScript bleibt deine einfache Godot-Schnittstelle.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## Was die Bridge heute schon kann\\r\\n\\r\\n- Python-Prozesse starten, \xfcberwachen und sauber beenden\\r\\n- asynchrone Tasks mit Priorit\xe4ten, Batching und Backpressure\\r\\n- strukturierte Fehler inklusive Python-Traceback in Godot\\r\\n- mehrere Python-Instanzen und Worker-Slots parallel\\r\\n- automatische projektbezogene `venv` mit Dependency-Verwaltung\\r\\n- Hot Reload von Python-Code aus dem Godot-Editor\\r\\n- DataRefs und Datei-Transport f\xfcr gro\xdfe numerische Ergebnisse\\r\\n- Crash-Restart mit exponentiellem Backoff und Health Monitoring\\r\\n\\r\\n## Der aktuelle Stand\\r\\n\\r\\nDie Python-Runtime ist durch eine umfassende Testsuite abgedeckt\\r\\n(90 Tests gr\xfcn). Die Godot-Integration folgt der Verifikations-Checkliste\\r\\nin der [Dokumentation](/docs/godot-verification).\\r\\n\\r\\n## Was als N\xe4chstes kommt\\r\\n\\r\\n1. End-to-End-Verifikation der Godot-Integration im Editor (P0)\\r\\n2. Verifikation des Shared-Memory-Datenpfads aus Godot heraus\\r\\n3. Automatisierte Builds f\xfcr den GDExtension-Hochleistungspfad\\r\\n\\r\\nDer einfachste Einstieg ist das\\r\\n[Hello-World-Beispiel](/docs/getting-started) \u2014 Godot startet Python dabei\\r\\nselbst, du brauchst kein Terminal."}]}}')}}]);